import sys

def is_valid_identifier(s: str) -> bool:
    if not s:
        return False
    # First char must be letter (A-Z, a-z) or underscore
    first = s[0]
    if not (first.isalpha() and first.isascii()) and first != '_':
        return False
    # Rest must be letter, digit, or underscore
    for ch in s[1:]:
        if not ((ch.isalnum() and ch.isascii()) or ch == '_'):
            return False
    return True

def is_keyword(s: str) -> bool:
    keywords = {
        'abstract','assert','boolean','break','byte','case','catch','char','class',
        'const','continue','default','do','double','else','enum','extends','final',
        'finally','float','for','goto','if','implements','import','instanceof','int',
        'interface','long','native','new','package','private','protected','public',
        'return','short','static','strictfp','super','switch','synchronized','this',
        'throw','throws','transient','try','void','volatile','while','true','false','null'
    }
    return s in keywords

def main():
    data = sys.stdin.read().strip()
    if not is_valid_identifier(data) or is_keyword(data):
        print("false")
    else:
        print("true")

if __name__ == "__main__":
    main()
